#!/usr/bin/env node
'use strict';
// 她的房间 · 最小 room 包 (test/fixtures/games/her-room/): what the unit tests, `node e2e/run.js room` and
// `PIXELPET_DEV_GAMES=1 npm start` play before the real art is made in the games repository
// (docs/her-room-design.md §5). Drawn here pixel by pixel — nothing generated by a model — in the room's
// palette (light blue #6FA8E8, white / cream, navy #2C4A8A ribbons, pale gold #E8D6A0): a light-blue wall with
// a lace dado rail, an arched window with lace curtains and bows, whale decals and a whale rug; the furniture
// (a princess bed, the bedside table, a desk with a monitor, a record player, a TV with a console, a whale
// bean bag) and the props in an atlas. One open room (dafeiyu) and the four 即将开放 ones.
//   node scripts/build-room-fixture.js          → writes the pack
//   node scripts/build-room-fixture.js --check  → exits 1 when the files on disk are not what it would write
const fs = require('node:fs');
const path = require('node:path');
const zlib = require('node:zlib');

const OUT = path.join(__dirname, '..', 'test', 'fixtures', 'games', 'her-room');
const K = 2; // one art pixel = K×K world pixels

// ---- a tiny raster + PNG -------------------------------------------------------------------------------------
const hex = (c) => (c === null ? [0, 0, 0, 0] : [parseInt(c.slice(1, 3), 16), parseInt(c.slice(3, 5), 16), parseInt(c.slice(5, 7), 16), c.length > 7 ? parseInt(c.slice(7, 9), 16) : 255]);
class Img {
  constructor(w, h, bg = null) { this.w = w; this.h = h; this.d = new Uint8Array(w * h * 4); if (bg) this.rect(0, 0, w, h, bg); }
  px(x, y, c) {
    x = Math.round(x); y = Math.round(y);
    if (x < 0 || y < 0 || x >= this.w || y >= this.h) return;
    const [r, g, b, a] = hex(c);
    const i = (y * this.w + x) * 4;
    this.d[i] = r; this.d[i + 1] = g; this.d[i + 2] = b; this.d[i + 3] = a;
  }
  get(x, y) { const i = (y * this.w + x) * 4; return this.d[i + 3]; }
  rect(x, y, w, h, c) { for (let j = 0; j < h; j++) for (let i = 0; i < w; i++) this.px(x + i, y + j, c); return this; }
  ell(cx, cy, rx, ry, c) { for (let y = Math.floor(cy - ry); y <= cy + ry; y++) for (let x = Math.floor(cx - rx); x <= cx + rx; x++) if (((x + 0.5 - cx) / rx) ** 2 + ((y + 0.5 - cy) / ry) ** 2 <= 1) this.px(x, y, c); return this; }
  hline(x, y, w, c) { return this.rect(x, y, w, 1, c); }
  vline(x, y, h, c) { return this.rect(x, y, 1, h, c); }
  // a 1-px outline round everything opaque
  outline(c) {
    const out = [];
    for (let y = 0; y < this.h; y++) for (let x = 0; x < this.w; x++) {
      if (this.get(x, y)) continue;
      const n = [[1, 0], [-1, 0], [0, 1], [0, -1]].some(([dx, dy]) => { const a = x + dx; const b = y + dy; return a >= 0 && b >= 0 && a < this.w && b < this.h && this.get(a, b) > 128; });
      if (n) out.push([x, y]);
    }
    for (const [x, y] of out) this.px(x, y, c);
    return this;
  }
  blit(src, x0, y0) {
    for (let y = 0; y < src.h; y++) for (let x = 0; x < src.w; x++) {
      const i = (y * src.w + x) * 4;
      if (!src.d[i + 3]) continue;
      const X = x0 + x; const Y = y0 + y;
      if (X < 0 || Y < 0 || X >= this.w || Y >= this.h) continue;
      const j = (Y * this.w + X) * 4;
      for (let k = 0; k < 4; k++) this.d[j + k] = src.d[i + k];
    }
  }
  scale(k) {
    const o = new Img(this.w * k, this.h * k);
    for (let y = 0; y < o.h; y++) for (let x = 0; x < o.w; x++) { const i = (Math.floor(y / k) * this.w + Math.floor(x / k)) * 4; const j = (y * o.w + x) * 4; for (let c = 0; c < 4; c++) o.d[j + c] = this.d[i + c]; }
    return o;
  }
  png() {
    const crcT = new Int32Array(256).map((_, n) => { let c = n; for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1; return c; });
    const crc = (buf) => { let c = -1; for (const b of buf) c = crcT[(c ^ b) & 255] ^ (c >>> 8); return (c ^ -1) >>> 0; };
    const chunk = (type, data) => { const len = Buffer.alloc(4); len.writeUInt32BE(data.length); const td = Buffer.concat([Buffer.from(type), data]); const cr = Buffer.alloc(4); cr.writeUInt32BE(crc(td)); return Buffer.concat([len, td, cr]); };
    const ihdr = Buffer.alloc(13);
    ihdr.writeUInt32BE(this.w, 0); ihdr.writeUInt32BE(this.h, 4); ihdr[8] = 8; ihdr[9] = 6; ihdr[10] = 0; ihdr[11] = 0; ihdr[12] = 0;
    const raw = Buffer.alloc((this.w * 4 + 1) * this.h);
    for (let y = 0; y < this.h; y++) { raw[y * (this.w * 4 + 1)] = 0; Buffer.from(this.d.buffer, y * this.w * 4, this.w * 4).copy(raw, y * (this.w * 4 + 1) + 1); }
    return Buffer.concat([Buffer.from([137, 80, 78, 71, 13, 10, 26, 10]), chunk('IHDR', ihdr), chunk('IDAT', zlib.deflateSync(raw, { level: 9 })), chunk('IEND', Buffer.alloc(0))]);
  }
}

// ---- palette ------------------------------------------------------------------------------------------------
const C = {
  wall: '#CFE3F8', wall2: '#BED7F3', blue: '#6FA8E8', blue2: '#4F8AD0', blueL: '#A9CBF2', navy: '#2C4A8A', navyD: '#1E3566',
  white: '#FFFFFF', cream: '#FFF8EC', cream2: '#EEE3CF', gold: '#E8D6A0', gold2: '#C9B278', pink: '#F6B8C8', pink2: '#E68AA6',
  floor: '#F3E6CC', floor2: '#E5D2AE', floor3: '#D8C196', glass: '#DDEFFF', dark: '#2A3550', screen: '#1F2A44', black: '#141A2A',
  green: '#8FD3B0', yellow: '#FFE08A', coin: '#F7C948', red: '#E86A7A',
};

// a navy bow, about 9×5
function bow(img, x, y, c = C.navy) {
  img.rect(x - 4, y - 2, 3, 4, c); img.rect(x + 2, y - 2, 3, 4, c); img.rect(x - 1, y - 1, 3, 3, C.navyD);
  img.px(x - 5, y - 1, c); img.px(x + 5, y - 1, c); img.px(x - 2, y + 2, c); img.px(x + 2, y + 2, c); img.px(x - 2, y + 3, c); img.px(x + 3, y + 3, c);
}
// lace: a row of little scallops along y, downwards
function lace(img, x0, y, w, c = C.white) {
  img.hline(x0, y, w, c);
  for (let x = x0; x < x0 + w; x += 4) { img.rect(x, y + 1, 3, 1, c); img.px(x + 1, y + 2, c); img.px(x + 1, y + 1, C.blueL); }
}
// a whale facing right
function whale(img, cx, cy, s, body = C.blue, belly = C.white) {
  img.ell(cx, cy, 9 * s, 5 * s, body);
  img.ell(cx + 1 * s, cy + 2.2 * s, 6 * s, 2.2 * s, belly);
  img.rect(cx - 12 * s, cy - 3 * s, 3 * s, 2 * s, body); img.rect(cx - 13 * s, cy - 5 * s, 2 * s, 2 * s, body); img.rect(cx - 13 * s, cy - 1 * s, 2 * s, 2 * s, body);
  img.rect(cx + 5 * s, cy - 2 * s, Math.max(1, s), Math.max(1, s), C.navyD);
  img.px(cx + 1 * s, cy - 6 * s, C.blueL); img.px(cx + 2 * s, cy - 7 * s, C.blueL); img.px(cx, cy - 7 * s, C.blueL);
}
function heart(img, x, y, c) { img.rect(x, y + 1, 7, 2, c); img.rect(x + 1, y, 2, 1, c); img.rect(x + 4, y, 2, 1, c); img.rect(x + 1, y + 3, 5, 1, c); img.rect(x + 2, y + 4, 3, 1, c); img.px(x + 3, y + 5, c); }

// ---- the background: 512×288 art px → 1024×576 ----------------------------------------------------------------
function background() {
  const W = 512; const H = 288; const FLOOR = 236;
  const b = new Img(W, H, C.wall);
  // wallpaper stripes and little dots
  for (let x = 0; x < W; x += 12) b.rect(x, 10, 4, FLOOR - 10, C.wall2);
  for (let y = 22; y < 180; y += 18) for (let x = (y / 18) % 2 ? 8 : 2; x < W; x += 12) b.px(x, y, C.white);
  // ceiling trim with lace
  b.rect(0, 0, W, 8, C.white); b.hline(0, 8, W, C.gold); lace(b, 0, 9, W);
  // the dado: white panels with a gold rail and lace on top
  b.rect(0, 188, W, FLOOR - 188, C.white); b.hline(0, 188, W, C.gold); b.hline(0, 189, W, C.gold2); lace(b, 0, 190, W, C.cream);
  for (let x = 6; x < W; x += 42) { b.rect(x, 198, 34, 32, C.cream); b.rect(x + 1, 199, 32, 30, C.white); b.hline(x, 198, 34, C.cream2); }
  // skirting
  b.rect(0, FLOOR - 4, W, 4, C.blue); b.hline(0, FLOOR - 4, W, C.navy);
  // the window: an arch (glass light; the engine paints the sky over it)
  const wx = 200; const wy = 45; const ww = 90; const wh = 100;
  b.ell(wx + ww / 2, wy + 22, ww / 2 + 4, 26, C.white); b.rect(wx - 4, wy + 22, ww + 8, wh - 22 + 4, C.white);
  b.ell(wx + ww / 2, wy + 22, ww / 2, 22, C.glass); b.rect(wx, wy + 22, ww, wh - 22, C.glass);
  b.vline(wx + ww / 2, wy, wh, C.white); b.hline(wx, wy + 52, ww, C.white);
  b.rect(wx - 8, wy + wh, ww + 16, 5, C.white); b.hline(wx - 8, wy + wh + 5, ww + 16, C.gold);
  // lace curtains, tied with bows
  for (const [x0, dir] of [[wx - 16, 1], [wx + ww + 2, -1]]) {
    for (let y = wy - 8; y < wy + wh + 14; y++) {
      const tie = y > wy + 60 && y < wy + 70;
      const w = tie ? 7 : 14 - Math.max(0, Math.round((y - (wy + 70)) * -0.05));
      b.rect(dir > 0 ? x0 : x0 + 14 - w, y, w, 1, (y % 4) ? C.white : C.cream);
      if (y % 6 === 0) b.px(x0 + 7, y, C.blueL);
    }
    bow(b, x0 + 7, wy + 64);
  }
  b.rect(wx - 20, wy - 12, ww + 40, 6, C.blue); lace(b, wx - 20, wy - 6, ww + 40); bow(b, wx + ww / 2, wy - 10);
  // whale decals and frames
  whale(b, 60, 60, 2, C.blueL, C.white); whale(b, 120, 40, 1, C.blueL, C.white); whale(b, 420, 70, 2, C.blueL, C.white); whale(b, 470, 120, 1, C.blueL, C.white);
  b.rect(340, 40, 40, 30, C.gold); b.rect(342, 42, 36, 26, C.blueL); b.rect(342, 58, 36, 10, C.blue); whale(b, 360, 54, 1, C.navy, C.white); // a picture of the sea
  heart(b, 152, 100, C.pink2); b.ell(160, 112, 9, 9, C.gold); b.ell(160, 112, 7, 7, C.glass); bow(b, 160, 101, C.navy);
  // the shell chandelier
  b.vline(256, 9, 18, C.gold2); b.ell(256, 30, 10, 5, C.cream); b.ell(256, 28, 8, 3, C.white); for (let i = -8; i <= 8; i += 4) b.px(256 + i, 34, C.gold);
  // the floor: cream planks
  b.rect(0, FLOOR, W, H - FLOOR, C.floor);
  for (let y = FLOOR + 6; y < H; y += 8) b.hline(0, y, W, C.floor2);
  for (let y = FLOOR; y < H; y += 8) for (let x = ((y / 8) % 2) * 24; x < W; x += 48) b.vline(x, y, 8, C.floor3);
  // the whale rug
  b.ell(256, 266, 78, 14, C.white); b.ell(256, 266, 74, 12, C.blueL); b.ell(258, 268, 46, 6, C.white);
  b.rect(176, 258, 8, 6, C.blueL); b.rect(172, 254, 6, 5, C.blueL); b.rect(172, 266, 6, 5, C.blueL); b.rect(312, 262, 2, 2, C.navy);
  return b.scale(K);
}

// ---- the atlas: each sprite drawn in art px, outlined, scaled K× ----------------------------------------------
function sprites() {
  const S = {};
  const add = (name, img) => { S[name] = img.outline(C.navyD).scale(K); };
  const raw = (name, img) => { S[name] = img.scale(K); };
  // the princess bed, side view: tall headboard on the left, mattress, footboard (bed-front) on the right
  {
    const b = new Img(140, 116);
    b.rect(2, 10, 10, 104, C.white); b.ell(7, 10, 5, 5, C.gold); // the head post
    b.rect(12, 30, 26, 70, C.cream); b.ell(25, 30, 13, 12, C.cream); b.ell(25, 31, 10, 9, C.white); bow(b, 25, 40);
    b.rect(126, 40, 10, 74, C.white); b.ell(131, 40, 5, 5, C.gold); // the foot post
    b.rect(2, 4, 136, 6, C.white); lace(b, 2, 10, 136); for (let x = 4; x < 136; x += 22) bow(b, x + 8, 8); // canopy
    for (let y = 12; y < 70; y++) { b.px(3 + (y % 3), y, C.white); b.px(135 - (y % 3), y, C.white); } // drapes
    b.rect(12, 78, 116, 14, C.white); b.hline(12, 78, 116, C.cream2); // the mattress
    b.rect(12, 92, 116, 14, C.blue); b.hline(12, 92, 116, C.navy); lace(b, 12, 105, 116); // the skirt
    b.ell(32, 72, 15, 8, C.white); b.ell(32, 71, 12, 6, C.cream); // pillow
    whale(b, 56, 72, 1); // a whale plush
    b.rect(4, 112, 6, 4, C.gold2); b.rect(128, 112, 6, 4, C.gold2);
    add('bed', b);
    const f = new Img(140, 116);
    f.rect(118, 62, 18, 52, C.white); f.ell(127, 62, 9, 7, C.white); f.ell(127, 63, 6, 5, C.cream); bow(f, 127, 70);
    f.rect(126, 40, 10, 74, C.white); f.ell(131, 40, 5, 5, C.gold);
    f.rect(12, 98, 116, 8, C.blue); f.hline(12, 98, 116, C.navy); lace(f, 12, 105, 114);
    f.rect(4, 112, 6, 4, C.gold2); f.rect(128, 112, 6, 4, C.gold2);
    add('bed-front', f);
    const q = new Img(104, 26);
    q.rect(0, 2, 104, 22, C.blue); q.rect(0, 0, 104, 4, C.white); lace(q, 0, 4, 104, C.cream);
    for (let y = 10; y < 24; y += 6) for (let x = (y % 12) ? 4 : 8; x < 104; x += 10) q.rect(x, y, 2, 2, C.white);
    bow(q, 78, 12); q.rect(0, 22, 104, 2, C.blue2);
    add('quilt', q);
  }
  // the bedside table with a shell lamp and cocoa
  {
    const n = new Img(44, 50);
    n.rect(2, 16, 40, 32, C.white); n.rect(2, 14, 40, 3, C.gold); n.rect(5, 20, 34, 11, C.cream); n.rect(5, 33, 34, 11, C.cream); n.px(22, 25, C.gold2); n.px(22, 38, C.gold2); bow(n, 22, 29, C.blue);
    n.rect(4, 46, 4, 4, C.gold2); n.rect(36, 46, 4, 4, C.gold2);
    n.rect(31, 8, 2, 6, C.gold2); n.ell(32, 6, 6, 4, C.pink); n.ell(32, 5, 4, 2, C.white); // shell lamp
    add('nightstand', n);
    const p = new Img(8, 4); p.rect(0, 0, 8, 4, C.dark); p.rect(1, 1, 6, 2, C.navy); raw('phone-on-table', p.outline(C.black));
    const pl = new Img(8, 13); pl.rect(0, 0, 8, 13, C.dark); pl.rect(1, 1, 6, 10, C.blueL); pl.rect(2, 5, 4, 2, C.blue); pl.rect(1, 4, 1, 2, C.blue); pl.px(5, 5, C.navyD); pl.rect(2, 8, 4, 1, C.white); pl.px(4, 12, C.white); add('phone-lit', pl);
    const co = new Img(8, 9); co.rect(1, 3, 5, 6, C.white); co.rect(6, 4, 2, 3, C.white); co.rect(2, 3, 3, 1, '#8A5A3C'); co.px(2, 0, C.white); co.px(4, 1, C.white); add('cocoa', co);
  }
  // the desk with a monitor (screen dark), a chair; the lamp is its own piece (swap)
  {
    const d = new Img(100, 92);
    d.rect(0, 46, 100, 6, C.white); d.hline(0, 46, 100, C.gold); d.rect(2, 52, 96, 3, C.cream2);
    d.rect(4, 55, 6, 37, C.white); d.rect(90, 55, 6, 37, C.white); d.rect(60, 55, 30, 18, C.cream); d.rect(62, 57, 26, 14, C.white); bow(d, 75, 64, C.navy);
    d.rect(36, 8, 40, 30, C.white); d.rect(38, 10, 36, 25, C.screen); d.rect(52, 38, 8, 6, C.white); d.rect(46, 44, 20, 2, C.cream2); // the monitor
    d.rect(28, 42, 10, 3, C.cream); d.rect(80, 41, 7, 5, C.pink); // keyboard-ish, a box
    add('desk', d);
    for (const [name, on] of [['desk-lamp', false], ['desk-lamp-on', true]]) {
      const l = new Img(18, 26);
      if (on) { l.ell(9, 9, 9, 8, '#FFF2B8A0'); }
      l.rect(8, 10, 2, 13, C.gold2); l.rect(4, 23, 10, 3, C.gold2);
      l.ell(9, 7, 7, 5, on ? C.yellow : C.cream); l.rect(2, 9, 14, 3, on ? C.yellow : C.cream); bow(l, 9, 10, C.navy);
      add(name, l);
    }
    const mb = new Img(36, 25, C.blueL); for (let y = 3; y < 23; y += 6) { mb.rect(2, y, 4, 4, C.white); mb.px(3, y + 1, C.blue); }
    raw('monitor-bg', mb);
  }
  // the record player on a cabinet (no record: the record is its own sprite, spinning)
  {
    const r = new Img(62, 76);
    r.rect(2, 30, 58, 44, C.white); r.rect(2, 28, 58, 3, C.gold); r.rect(6, 36, 24, 32, C.cream); r.rect(32, 36, 24, 32, C.cream); bow(r, 18, 46, C.navy); bow(r, 44, 46, C.navy);
    r.rect(4, 72, 5, 4, C.gold2); r.rect(53, 72, 5, 4, C.gold2);
    r.rect(6, 14, 50, 14, C.blue); r.rect(6, 14, 50, 2, C.blueL); r.rect(8, 16, 30, 8, C.navy); r.rect(48, 12, 2, 8, C.gold2); r.rect(42, 19, 7, 2, C.gold2); // the turntable
    r.ell(48, 6, 5, 5, C.gold); r.ell(48, 6, 3, 3, C.cream); r.rect(47, 9, 2, 5, C.gold2); // a little horn
    add('record-cabinet', r);
    const disc = new Img(26, 26); disc.ell(13, 13, 13, 13, C.black); disc.ell(13, 13, 10, 10, '#2C3346'); disc.ell(13, 13, 5, 5, C.blue); disc.ell(13, 13, 1.5, 1.5, C.white); disc.rect(6, 6, 3, 1, '#4A5470');
    raw('record-disc', disc);
  }
  // the TV cabinet with a retro TV (screen dark) and a console
  {
    const t = new Img(92, 96);
    t.rect(0, 56, 92, 38, C.white); t.rect(0, 54, 92, 3, C.gold); t.rect(4, 62, 40, 26, C.cream); t.rect(48, 62, 40, 26, C.cream); bow(t, 24, 72, C.blue); bow(t, 68, 72, C.blue);
    t.rect(4, 92, 5, 4, C.gold2); t.rect(83, 92, 5, 4, C.gold2);
    t.rect(14, 6, 60, 44, C.blue); t.rect(14, 6, 60, 3, C.blueL); t.rect(18, 10, 48, 34, C.screen); t.rect(68, 14, 4, 4, C.gold); t.rect(68, 22, 4, 4, C.gold); t.rect(24, 50, 6, 4, C.blue); t.rect(58, 50, 6, 4, C.blue);
    t.rect(28, 0, 2, 6, C.gold2); t.rect(56, 0, 2, 6, C.gold2); // antennas
    t.rect(76, 46, 14, 8, C.cream); t.rect(78, 48, 4, 2, C.blue); t.px(86, 49, C.pink2); // the console
    add('tv-cabinet', t);
    for (let i = 0; i < 4; i++) {
      const f = new Img(48, 34, C.blueL);
      f.rect(0, 26, 48, 8, C.green); for (let x = -((i * 6) % 12); x < 48; x += 12) f.rect(x, 26, 6, 2, '#6CBF95');
      for (let k = 0; k < 4; k++) { const cx = (k * 14 + 40 - i * 4) % 52 - 2; if (cx > 1 && cx < 46) f.ell(cx, 14 - ((k + i) % 2) * 4, 2, 2, C.coin); }
      { const wy = 20 - [0, 5, 8, 4][i]; f.ell(14, wy, 6, 4, C.blue); f.ell(15, wy + 2, 4, 1.5, C.white); f.rect(6, wy - 2, 2, 2, C.blue); f.rect(5, wy - 4, 2, 2, C.blue); f.px(17, wy - 1, C.navyD); }
      f.rect(2, 2, 10, 2, C.white); f.rect(2 + i * 2, 2, 2, 2, C.coin);
      raw(`tv-${i + 1}`, f);
    }
    const c = new Img(13, 8); c.ell(3, 4, 3, 3, C.white); c.ell(9, 4, 3, 3, C.white); c.rect(3, 2, 6, 5, C.white); c.px(2, 4, C.navy); c.px(10, 3, C.pink2); c.px(9, 5, C.blue); add('controller', c);
  }
  // the whale bean bag
  {
    const w = new Img(58, 30);
    w.ell(30, 18, 26, 12, C.blue); w.ell(32, 22, 18, 6, C.white); w.rect(0, 10, 8, 6, C.blue); w.rect(0, 18, 8, 6, C.blue); w.rect(44, 12, 2, 2, C.navyD); w.ell(46, 18, 3, 2, C.pink);
    add('whale-beanbag', w);
  }
  // particles: notes, the two Z bubbles (no letters: round bubbles), a heart, a star
  {
    const note = (k) => { const n = new Img(9, 11); n.rect(5, 0, 1, 8, C.navy); n.rect(6, 0, 3, 2, C.navy); n.ell(3, 8, 3, 2.5, [C.navy, C.blue2, C.pink2][k]); if (k === 2) { n.rect(1, 0, 1, 8, C.navy); n.rect(1, 0, 5, 1, C.navy); } return n; };
    for (let k = 0; k < 3; k++) add(`note${k + 1}`, note(k));
    const z1 = new Img(11, 11); z1.ell(5.5, 5.5, 5, 5, C.white); z1.ell(5.5, 5.5, 3, 3, C.blueL); add('z1', z1);
    const z2 = new Img(8, 8); z2.ell(4, 4, 3.5, 3.5, C.white); z2.ell(4, 4, 2, 2, C.blueL); add('z2', z2);
    const h = new Img(8, 7); heart(h, 0, 0, C.pink2); h.px(2, 1, C.white); add('heart', h);
    const st = new Img(9, 9); st.rect(4, 0, 1, 9, C.yellow); st.rect(0, 4, 9, 1, C.yellow); st.rect(3, 3, 3, 3, C.yellow); st.px(4, 4, C.white); add('star', st);
  }
  return S;
}

// shelf-pack the sprites into one atlas
function pack(S) {
  const names = Object.keys(S);
  const W = 640;
  let x = 0; let y = 0; let row = 0;
  const at = {};
  for (const n of names.sort((a, b) => S[b].h - S[a].h || a.localeCompare(b))) {
    const s = S[n];
    if (x + s.w + 2 > W) { x = 0; y += row + 2; row = 0; }
    at[n] = { x, y, w: s.w, h: s.h };
    x += s.w + 2; row = Math.max(row, s.h);
  }
  const atlas = new Img(W, y + row);
  for (const n of names) atlas.blit(S[n], at[n].x, at[n].y);
  return { atlas, index: Object.fromEntries(Object.keys(at).sort().map((n) => [n, at[n]])) };
}

