function build() {
  const S = sprites();
  const { atlas, index } = pack(S);
  const m = manifest();
  return {
    'manifest.json': Buffer.from(`${JSON.stringify(m, null, 2)}\n`),
    'dafeiyu-room.png': background().png(),
    'dafeiyu-atlas.png': atlas.png(),
    'dafeiyu-sprites.json': Buffer.from(`${JSON.stringify(index, null, 2)}\n`),
  };
}

if (require.main === module) {
  const files = build();
  if (process.argv.includes('--check')) {
    const stale = Object.entries(files).filter(([n, b]) => { try { return !fs.readFileSync(path.join(OUT, n)).equals(b); } catch { return true; } }).map(([n]) => n);
    if (stale.length) { console.error(`her-room fixture is stale: ${stale.join(', ')} (node scripts/build-room-fixture.js)`); process.exit(1); }
    console.log('her-room fixture is up to date');
  } else {
    fs.mkdirSync(OUT, { recursive: true });
    for (const [n, b] of Object.entries(files)) fs.writeFileSync(path.join(OUT, n), b);
    console.log(`wrote ${Object.keys(files).map((n) => `${n} (${files[n].length} B)`).join(', ')} → ${path.relative(process.cwd(), OUT)}`);
  }
}

module.exports = { build, OUT, Img };
